import { CommonModule } from '@angular/common';
import { Component } from '@angular/core';
import { InputComponent } from '../../../shared/components/input/input.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { FormBuilder, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { LoginService } from '../../services/login/login.service';

@Component({
  selector: 'app-forgotpassword',
  standalone: true,
  providers: [LoginService],
  imports: [CommonModule, InputComponent, ButtonComponent, ReactiveFormsModule],
  templateUrl: './forgotpassword.component.html',
  styleUrl: './forgotpassword.component.scss'
})
export class ForgotpasswordComponent {
  loginForm: FormGroup;
  resetpass: FormGroup;
  keepMeLogin: boolean = false;
  enterpassword: boolean = false;
  isloading: boolean = false;
  getYear: any = new Date().getFullYear();
  constructor(public logS: LoginService, private formBuilder: FormBuilder) {

  }

  ngOnInit(): void {
    this.loginForm = this.formBuilder.group({
      cEmail: ['', [Validators.required, Validators.email]],
    });
    this.resetpass = this.formBuilder.group({
      newpassword: ['', [Validators.required, Validators.email]],
      retypepassword: ['', [Validators.required, Validators.email]],
    });
  }


  async onSubmit() {
    
    this.isloading = true;
    if (this.loginForm.valid) {
      // let res: any = await this.logS.login(this.loginForm.value, this.keepMeLogin);
      this.isloading = false;
      this.enterpassword = true;
      // if (res) {
      //   this.router.navigate(['/user/dashboard']);
      // }
    }
  }
}
